INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind hier die Rollen unklar verteilt?', 2, '[{"text": "Nein", "correct": true, "because": "Klare Rollenverteilung"}, {"text": "Ja", "correct": false, "because": "Strukturierte Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle steuert das Projekt?', 3, '[{"text": "Projektleiter", "correct": true, "because": "Gesamtverantwortung"}, {"text": "Entwickler", "correct": false, "because": "Code umsetzen"}, {"text": "Tester", "correct": false, "because": "Qualität prüfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen gehören zur Aufgabenstruktur?', 5, '[{"text": "Projektleiter", "correct": true, "because": "Projektmanagement"}, {"text": "Tester", "correct": true, "because": "Qualitätssicherung"}, {"text": "Unklare Rollen", "correct": false, "because": "Klar definierte Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Entwickler schreiben Code. b) Tester leiten das Projekt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Projektleiter leitet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei dieser Rollenverteilung?', 4, '[{"text": "Projektleiter", "correct": false, "because": "Projektsteuerung"}, {"text": "Entwickler", "correct": false, "because": "Entwicklung zentral"}, {"text": "Unklare Verantwortlichkeiten", "correct": true, "because": "Klar definierte Rollen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Tester hier entwickeln?', 2, '[{"text": "Nein", "correct": true, "because": "Tester prüfen, Entwickler kodieren"}, {"text": "Ja", "correct": false, "because": "Rollen getrennt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle prüft die Qualität?', 3, '[{"text": "Tester", "correct": true, "because": "Tests durchführen"}, {"text": "Projektleiter", "correct": false, "because": "Projektmanagement"}, {"text": "Entwickler", "correct": false, "because": "Code schreiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortlichkeiten fördern den Ablauf?', 5, '[{"text": "Projektleiter steuert", "correct": true, "because": "Koordination sichern"}, {"text": "Entwickler implementieren", "correct": true, "because": "Code erstellen"}, {"text": "Tester entwickeln", "correct": false, "because": "Rollen getrennt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Projektleiter plant. b) Entwickler testen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tester testen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Projektleiter", "correct": false, "because": "Projektsteuerung"}, {"text": "Tester", "correct": false, "because": "Qualitätssicherung"}, {"text": "Unklare Rollen", "correct": true, "because": "Klarheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Tester hier für die Planung zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Projektleiter plant"}, {"text": "Ja", "correct": false, "because": "Tester prüfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen sichern die Qualität?', 4, '[{"text": "Tester", "correct": true, "because": "Tests durchführen"}, {"text": "Entwickler", "correct": true, "because": "Qualität im Code"}, {"text": "Projektleiter testet", "correct": false, "because": "Leitung, nicht Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Entwickler hier leiten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Projektleiter leitet"}, {"text": "Ja", "correct": false, "because": "Entwickler kodieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich als Projektleiter?', 3, '[{"text": "Planung und Steuerung", "correct": true, "because": "Projektmanagement"}, {"text": "Code schreiben", "correct": false, "because": "Entwickleraufgabe"}, {"text": "Tests durchführen", "correct": false, "because": "Testeraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tester prüfen das Produkt. b) Projektleiter entwickelt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Projektleiter leitet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat diese Rollenverteilung?', 5, '[{"text": "Klarheit", "correct": true, "because": "Definierte Aufgaben"}, {"text": "Effizienz", "correct": true, "because": "Spezialisierung"}, {"text": "Überlappende Rollen", "correct": false, "because": "Klar getrennt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Entwickler", "correct": false, "because": "Code umsetzen"}, {"text": "Tester", "correct": false, "because": "Qualität prüfen"}, {"text": "Flexible Rollen", "correct": true, "because": "Klar definierte Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Entwickler hier für Tests zuständig?', 3, '[{"text": "Nein", "correct": true, "because": "Tester übernehmen Tests"}, {"text": "Ja", "correct": false, "because": "Rollen getrennt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Projektleiter testet?', 2, '[{"text": "Nein", "correct": true, "because": "Projektleiter steuert"}, {"text": "Ja", "correct": false, "because": "Tester prüfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für die Implementierung?', 4, '[{"text": "Entwickler", "correct": true, "because": "Code schreiben"}, {"text": "Projektleiter", "correct": false, "because": "Projektmanagement"}, {"text": "Tester", "correct": false, "because": "Qualitätssicherung"}]');
